const choose = (context: LocalizedText): LocalizedText => T(
  context.en + ' ' + WHICH.en, context.it + ' ' + WHICH.it, context.pt + ' ' + WHICH.pt,
  context.es + ' ' + WHICH.es, context.fr + ' ' + WHICH.fr, context.de + ' ' + WHICH.de
);

